// A tiny fake of HttpTestingController: record requests, let the test flush them.
class Controller {
  constructor() { this.open = []; }
  request(url) { // what the service calls instead of real HTTP
    return new Promise((resolve, reject) => this.open.push({ url, resolve, reject }));
  }
  expectOne(url) { // assert exactly one pending request for the URL
    const m = this.open.filter(r => r.url === url);
    if (m.length !== 1) throw new Error('expected 1 request for ' + url + ', got ' + m.length);
    this.open.splice(this.open.indexOf(m[0]), 1);
    return m[0];
  }
  verify() { // fail if any request was not handled
    if (this.open.length) throw new Error('unexpected: ' + this.open.map(r => r.url));
  }
}
// Service under test: retries once on failure.
async function loadUser(http, id) {
  try { return await http.request('/api/users/' + id); }
  catch (e) { return await http.request('/api/users/' + id); }
}
(async () => {
  const http = new Controller();
  const p = loadUser(http, 7);
  http.expectOne('/api/users/7').reject(new Error('500'));  // first attempt fails
  await Promise.resolve(); await Promise.resolve();
  http.expectOne('/api/users/7').resolve({ id: 7, name: 'Ada' }); // retry succeeds
  console.log('result:', await p);
  http.verify();
  console.log('verify passed: no stray requests');
})();

// Virtual clock: test a 300ms debounce without waiting in real time.
class Clock {
  constructor() { this.now = 0; this.tasks = []; }
  setTimeout(fn, ms) { const t = { at: this.now + ms, fn, live: true }; this.tasks.push(t); return t; }
  clear(t) { if (t) t.live = false; }
  tick(ms) { // advance virtual time, firing due tasks in order
    const end = this.now + ms;
    for (;;) {
      const due = this.tasks.filter(t => t.live && t.at <= end).sort((a, b) => a.at - b.at)[0];
      if (!due) break;
      this.now = due.at; due.live = false; due.fn();
    }
    this.now = end;
  }
}
function debounce(clock, fn, ms) {
  let timer;
  return (v) => { clock.clear(timer); timer = clock.setTimeout(() => fn(v), ms); };
}
const clock = new Clock();
const calls = [];
const search = debounce(clock, v => calls.push(clock.now + 'ms:' + v), 300);
search('a'); clock.tick(100);   // t=100
search('ab'); clock.tick(100);  // t=200, restarts the timer
search('abc'); clock.tick(299); // t=499, still waiting
console.log('before 300ms quiet:', JSON.stringify(calls));
clock.tick(1);                  // t=500 -> fires once
console.log('after 300ms quiet: ', JSON.stringify(calls));

// Interceptor idea: many requests get 401 at once, but only ONE refresh is made.
let refreshCalls = 0, token = 'old';
let refreshing = null;                       // shared in-flight refresh
function refresh() {
  if (!refreshing) {
    refreshCalls++;
    refreshing = Promise.resolve().then(() => { token = 'new'; refreshing = null; });
  }
  return refreshing;
}
const server = (url, t) => (t === 'new' ? 'ok ' + url : '401');
async function call(url) {
  let r = server(url, token);
  if (r === '401') {
    await refresh();                         // all waiters share one refresh
    r = server(url, token);                  // retry exactly once, no loop
  }
  return r;
}
(async () => {
  const out = await Promise.all(['/a', '/b', '/c'].map(call));
  console.log('results:', out);
  console.log('refresh calls:', refreshCalls);
})();

// Shard slow tests across workers: LPT = longest test first, onto the least-loaded worker.
const tests = { a: 90, b: 70, c: 60, d: 40, e: 30, f: 20, g: 10 }; // seconds
function shard(tests, workers) {
  const bins = Array.from({ length: workers }, () => ({ load: 0, names: [] }));
  const sorted = Object.entries(tests).sort((x, y) => y[1] - x[1]);
  for (const [name, sec] of sorted) {
    bins.sort((x, y) => x.load - y.load);   // pick least-loaded worker
    bins[0].load += sec; bins[0].names.push(name);
  }
  return bins;
}
const naive = [0, 1, 2].map(i => Object.entries(tests).filter((_, k) => k % 3 === i)
  .reduce((s, [, v]) => s + v, 0));
console.log('tests:', JSON.stringify(tests));
console.log('round-robin loads:', naive, 'wall time', Math.max(...naive));
const bins = shard(tests, 3);
console.log('LPT loads:', bins.map(b => b.load + ' [' + b.names + ']').join(' | '));
console.log('wall time', Math.max(...bins.map(b => b.load)));
